        }
    )
    agent_protocol_audit = audit_agent_protocol(output)
    checks.append(
        {
            "name": "agent-protocol-valid",
            "passed": agent_protocol_audit.get("status") == "passed",
            "detail": agent_protocol_audit,
        }
    )
    if state["format"] == "both":
        markdown_projection = projections["markdown"]
        logseq_projection = projections["logseq-db"]
        md_pages = {(item["id"], item["title"], item["page_type"], item["human_page_kind"], item.get("tag")) for item in markdown_projection["pages"]}
        db_pages = {(item["id"], item["title"], item["page_type"], item["human_page_kind"], item.get("tag")) for item in logseq_projection["pages"]}
        md_links = {json.dumps(item, sort_keys=True, ensure_ascii=False) for item in markdown_projection["links"]}
        db_links = {json.dumps(item, sort_keys=True, ensure_ascii=False) for item in logseq_projection["links"]}
        owner_equal = markdown_projection["entity_owner_pages"] == logseq_projection["entity_owner_pages"]
        source_equal = markdown_projection["source_manifest"] == logseq_projection["source_manifest"]
        edn_equal = markdown_projection["normalized_edn_sha256"] == logseq_projection["normalized_edn_sha256"]
        config_equal = (
            markdown_projection.get("page_config") == logseq_projection.get("page_config") == page_config
            and markdown_projection.get("page_config_sha256") == logseq_projection.get("page_config_sha256") == config_hash
        )
        checks.append({
            "name": "dual-projection-parity",
            "passed": md_pages == db_pages and md_links == db_links and owner_equal and source_equal and edn_equal and config_equal,
            "detail": {
                "page_delta": sorted(md_pages ^ db_pages),
                "link_delta": sorted(md_links ^ db_links),
                "entity_ownership_equal": owner_equal,
                "source_manifest_equal": source_equal,
                "normalized_edn_equal": edn_equal,
                "page_config_equal": config_equal,
            },
        })
    status = "passed" if all(item["passed"] for item in checks) else "failed"
    result = {"schema_version": SCHEMA_VERSION, "status": status, "checks": checks, "projections": projections, "audited_at_utc": utc_now()}
    json_write(output / "audit" / "global.json", result)
    write_marker(
        output,
        ".pending-agent-review" if status == "passed" else ".failed",
        {"status": "global-audit-passed-finalize-required" if status == "passed" else "failed", "audit": str((output / "audit" / "global.json").resolve())},
    )
    return result

def _version_matches(expected: str, output: str) -> bool:
    lowered = output.lower()
    return expected.lower() in lowered or (len(expected) == 40 and expected[:7].lower() in lowered)

def private_runtime_root() -> Path:
    override = os.environ.get("CKB_RUNTIME_ROOT")
    if override:
        return Path(override).expanduser().resolve()
    return Path.home() / ".codex" / "cache" / "code-knowledge-builder" / "runtime" / "win-x64"

def _runtime_bin_candidates() -> list[Path]:
    root = private_runtime_root()
    if not root.is_dir():
        return []
    result: list[Path] = []
    for lock_dir in sorted(root.iterdir(), reverse=True):
        for rel in ("bin", "node", "python", "llvm/bin", "logseq", "dotnet", "dotnet-tools"):
            path = lock_dir / rel
            if path.is_dir():
                result.append(path)
    return result

def resolve_executable(name: str) -> str | None:
    env_name = "CKB_" + re.sub(r"[^A-Za-z0-9]", "_", name).upper() + "_COMMAND"
    if os.environ.get(env_name):
        return os.environ[env_name]
    names = [name]
    if os.name == "nt":
        names.extend([name + ".cmd", name + ".exe"])
    for directory in _runtime_bin_candidates():
        for candidate in names:
            path = directory / candidate
            if path.is_file():
                return str(path.resolve())
    for candidate in names:
        found = shutil.which(candidate)
        if found:
            return found
    return None

def path_to_uri(path: Path) -> str:
    value = path.resolve().as_posix()
    if os.name == "nt":
        return "file:///" + quote(value, safe="/:@")
    return "file://" + quote(value, safe="/:@")

def uri_to_path(uri: str) -> Path:
    parsed = urlparse(uri)
    value = unquote(parsed.path)
    if os.name == "nt" and value.startswith("/") and len(value) > 2 and value[2] == ":":
        value = value[1:]
    return Path(value).resolve()

class LspClient:
    def __init__(self, command: list[str], cwd: Path, env: dict[str, str] | None = None):
        self.command = command
        self.cwd = cwd
        self.env = env
        self.process: subprocess.Popen[bytes] | None = None
        self._id = 0
        self._messages: "queue.Queue[dict[str, Any]]" = queue.Queue()
        self._pending: dict[int, dict[str, Any]] = {}
        self.transcript: list[dict[str, Any]] = []
        self.stderr: list[str] = []

    def start(self) -> None:
        self.process = subprocess.Popen(
            self.command,
            cwd=str(self.cwd),
            env=self.env,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            **background_process_options(),
        )
        threading.Thread(target=self._read_stdout, daemon=True).start()
        threading.Thread(target=self._read_stderr, daemon=True).start()

    def _read_stdout(self) -> None:
        assert self.process and self.process.stdout
        stream = self.process.stdout
        while True:
            headers: dict[str, str] = {}
            while True:
                line = stream.readline()
                if not line:
                    return
                if line in (b"\r\n", b"\n"):
                    break
                key, value = line.decode("ascii", errors="replace").split(":", 1)
                headers[key.lower()] = value.strip()
            length = int(headers.get("content-length", "0"))
            body = stream.read(length)
            if not body:
                return
            message = json.loads(body.decode("utf-8"))
            self.transcript.append({"direction": "in", "message": message})
            self._messages.put(message)

    def _read_stderr(self) -> None:
        assert self.process and self.process.stderr
        for line in iter(self.process.stderr.readline, b""):
            self.stderr.append(line.decode("utf-8", errors="replace").rstrip())

    def send(self, message: dict[str, Any]) -> None:
        assert self.process and self.process.stdin
        body = json.dumps(message, separators=(",", ":")).encode("utf-8")
        header = f"Content-Length: {len(body)}\r\n\r\n".encode("ascii")
        self.transcript.append({"direction": "out", "message": message})
        self.process.stdin.write(header + body)
        self.process.stdin.flush()

    def notify(self, method: str, params: Any) -> None:
        self.send({"jsonrpc": "2.0", "method": method, "params": params})

    def request(self, method: str, params: Any, timeout: int = 60) -> Any:
        self._id += 1
        request_id = self._id
        self.send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if request_id in self._pending:
                message = self._pending.pop(request_id)
            else:
                try:
                    message = self._messages.get(timeout=min(0.5, max(0.01, deadline - time.monotonic())))
                except queue.Empty:
                    continue
            if message.get("method") and "id" in message:
                server_method = message.get("method")
                if server_method == "workspace/configuration":
                    items = (message.get("params") or {}).get("items") or []
                    server_result: Any = [{} for _ in items]
                elif server_method in {"client/registerCapability", "client/unregisterCapability", "window/workDoneProgress/create"}:
                    server_result = None
                else:
                    server_result = None
                self.send({"jsonrpc": "2.0", "id": message["id"], "result": server_result})
                continue
            if message.get("id") == request_id:
                if "error" in message:
                    raise CkbError(f"LSP {method} failed: {message['error']}")
                return message.get("result")
            if "id" in message:
                self._pending[int(message["id"])] = message
        raise CkbError(f"LSP request timed out: {method}")

    def stop(self) -> int | None:
        if not self.process:
            return None
        try:
            self.request("shutdown", None, timeout=10)
            self.notify("exit", None)
        except Exception:
            pass
        try:
            return self.process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self.process.terminate()
        try:
            return self.process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self.process.kill()
            return self.process.wait(timeout=5)

